import {vendorUnitCost} from "../../../../shared/culinary/vendorUnitCost.js";
import {useState} from "react";
import {Button,Form,Modal} from "react-bootstrap";
import Alert from "../AppAlert.jsx";
const id=value=>typeof value==='object'?value?._id||'':value||'';
export function priceUpdatePayload(product,values){return {business:id(product.business),vendor:id(product.vendor),ingredient:id(product.ingredient),packCost:Number(values.packCost),unitCost:Number(values.unitCost),unitCostOverride:true,effectiveDate:values.effectiveDate};}
export default function UpdateProductPrice({product,onClose,onSaved}){
 const [values,setValues]=useState({packCost:String(product.packCost??''),unitCost:String(product.unitCost??0),effectiveDate:new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())});
 const [saving,setSaving]=useState(false),[error,setError]=useState('');
 const change=event=>{const {name,value}=event.target;setValues(current=>{const next={...current,[name]:value};if(name==='packCost'){const calculated=vendorUnitCost({...product,packCost:value});if(calculated)next.unitCost=String(calculated.cost);}return next;});};
 const save=async event=>{event.preventDefault();if(saving)return;setSaving(true);setError('');try{const response=await fetch(`/api/vendor-ingredient-prices/${id(product)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(priceUpdatePayload(product,values))});const result=await response.json().catch(()=>null);if(!response.ok)throw new Error(result?.message||'Price could not be updated.');onSaved(result.vendorIngredientPrice);onClose();}catch(error){setError(error.message);}finally{setSaving(false);}};
 return <Modal show onHide={()=>!saving&&onClose()} centered><Modal.Header closeButton={!saving}><Modal.Title>Update Price</Modal.Title></Modal.Header><Form onSubmit={save}><Modal.Body>{error?<Alert variant="danger">{error}</Alert>:null}<div className="vendor-price-update-fields"><Form.Group><Form.Label>Product</Form.Label><Form.Control value={product.name||''} disabled/></Form.Group><Form.Group><Form.Label>Brand</Form.Label><Form.Control value={product.brand||'—'} disabled/></Form.Group><Form.Group><Form.Label>Pack</Form.Label><Form.Control value={product.imperialDisplay||product.metricDisplay||product.packSizeName||'—'} disabled/></Form.Group>{[['packCost','Pack Cost'],['unitCost','Unit Cost'],['effectiveDate','Effective Date']].map(([name,label])=><Form.Group key={name}><Form.Label htmlFor={'price-update-'+name}>{label}</Form.Label><Form.Control id={'price-update-'+name} name={name} type={name==='effectiveDate'?'date':'number'} min={name==='effectiveDate'?undefined:'0'} step={name==='effectiveDate'?undefined:'any'} value={values[name]} onChange={change} disabled={saving} required/></Form.Group>)}</div></Modal.Body><Modal.Footer><Button variant="outline-primary" disabled={saving} onClick={onClose}>Cancel</Button><Button type="submit" variant="primary" disabled={saving}>{saving?'Saving…':'Save Price'}</Button></Modal.Footer></Form></Modal>;
}
